function openWriteChar(chars, label, back){
  const I=rdBuildIndex();
  const list=[...new Set(String(chars||"").match(/[一-鿿]/g)||[])].map(ch=>{
    const ko=I.byK.get(ch)||I.byW.get(ch)||"";
    return {front:ch, romaji:"", ko:String(ko).split(/[,，·]/)[0].trim(), speak:ch};
  });
  if(!list.length){ toast("이 단어엔 한자가 없어요"); return; }
  wrAdhoc=list; wrAdhocLabel=label||"이 단어"; wrCat="_adhoc"; wrIdx=0;
  wrBack=back||"rdRead"; wrOrderMode=2;                 // 책에서 왔으면 획순을 처음부터 보여 준다
  const ob=$("wrOrderBtn"); if(ob) ob.textContent="획순: 번호+선";
  closeWordPop(); openWriting();                        // wrLoad 안에서 획순을 그린다(중복 호출 금지)
}

